 "signals": [
  {
   "name": "t0",
   "init": "now()"
  },
  {
   "name": "clock",
   "init": "0",
   "on": [
    {
     "events": {
      "type": "timer",
      "throttle": 40
     },
     "update": "min(now() - t0, 4600)"
    }
   ]
  },
  {
   "name": "t",
   "update": "min(1, clock / 4500)"
  },
  {
   "name": "nD0",
   "update": "length(data(''deadT0''))"
  },
  {
   "name": "nD1",
   "update": "length(data(''deadT1''))"
  },
  {
   "name": "nD",
   "update": "length(data(''deadAll''))"
  },
  {
   "name": "nA0",
   "update": "length(data(''aliveT0''))"
  },
  {
   "name": "nA1",
   "update": "length(data(''aliveT1''))"
  },
  {
   "name": "nA2",
   "update": "length(data(''aliveT2''))"
  },
  {
   "name": "nA",
   "update": "length(data(''aliveAll''))"
  },
  {
   "name": "nB",
   "update": "length(data(''bornAll''))"
  },
  {
   "name": "nHal",
   "update": "length(data(''halBig''))"
  },
  {
   "name": "dEnd0",
   "update": "40 + nD0 * 32"
  },
  {
   "name": "dEnd",
   "update": "dEnd0 + 8 + nD1 * 12"
  },
  {
   "name": "C0",
   "update": "dEnd + 20"
  },
  {
   "name": "cEnd0",
   "update": "C0 + nA0 * 29"
  },
  {
   "name": "cEnd1",
   "update": "cEnd0 + 8 + nA1 * 9"
  },
  {
   "name": "cEnd",
   "update": "cEnd1 + 8 + nA2 * 6"
  },
  {
   "name": "B0",
   "update": "cEnd + 20"
  },
  {
   "name": "hov",
   "value": null,
   "on": [
    {
     "events": "@hit:mouseover",
     "update": "datum"
    },
    {
     "events": "@hit:mouseout",
