  {
   "name": "rows",
   "source": "dataset",
   "transform": [
    {
     "type": "filter",
     "expr": "datum.Category !== ''Other Responses''"
    },
    {
     "type": "formula",
     "as": "c",
     "expr": "datum[''People Childhood''] || 0"
    },
    {
     "type": "formula",
     "as": "a",
     "expr": "datum[''People Adult''] || 0"
    },
    {
     "type": "formula",
     "as": "k",
     "expr": "datum[''People Kept''] || 0"
    },
    {
     "type": "filter",
     "expr": "datum.c > 0 || datum.a > 0"
    },
    {
     "type": "lookup",
     "from": "labels",
     "key": "Fear",
     "fields": [
      "Fear"
     ],
     "values": [
      "label"
     ],
     "as": [
      "lab0"
     ]
    },
    {
     "type": "formula",
     "as": "label",
     "expr": "datum.lab0 || datum.FearShort || datum.Fear"
    },
    {
     "type": "formula",
     "as": "hal",
     "expr": "datum.Category === ''Dark, Unknown & Supernatural''"
    },
    {
     "type": "formula",
     "as": "kind",
     "expr": "datum.a === 0 ? ''dead'' : datum.c === 0 ? ''born'' : ''alive''"
    },
    {
     "type": "formula",
     "as": "size",
     "expr": "datum.kind === ''dead'' ? datum.c : datum.a"
    },
    {
     "type": "formula",
     "as": "tier",
     "expr": "datum.kind === ''dead'' ? (datum.c >= 3 ? 0 : 1) : datum.kind === ''born'' ? 0 : (datum.a >= 6 ? 0 : datum.a >= 3 ? 1 : 2)"
    },
    {
     "type": "formula",
     "as": "gw",
     "expr": "16 + datum.a * 1.5"
    },
    {
     "type": "formula",
     "as": "gstep",
     "expr": "datum.kind === ''born'' ? (datum.a >= 3 ? max(datum.gw + 4, 30) : datum.gw + 4) : 0"
    },
    {
     "type": "window",
     "groupby": [
      "kind",
      "tier"
     ],
     "sort": {
      "field": [
       "size",
       "label"
      ],
      "order": [
       "descending",
       "ascending"
      ]
     },
     "ops": [
      "row_number",
      "sum"
     ],
     "fields": [
      null,
      "gstep"
     ],
     "as": [
      "rn",
      "gcum"
     ],
     "frame": [
      null,
      0
     ]
    }
   ]
  },
