     "as": "idx",
     "expr": "datum.kind === ''dead'' ? (datum.tier === 0 ? datum.rn - 1 : nD0 + datum.rn - 1) : datum.kind === ''born'' ? datum.rn - 1 : (datum.tier === 0 ? datum.rn - 1 : datum.tier === 1 ? nA0 + datum.rn - 1 : nA0 + nA1 + datum.rn - 1)"
    },
    {
     "type": "formula",
     "as": "x",
     "expr": "datum.kind === ''dead'' ? (datum.tier === 0 ? 40 + 14.0 + (datum.rn - 1) * 32 : dEnd0 + 8 + 5.0 + (datum.rn - 1) * 12) : datum.kind === ''born'' ? B0 + datum.gcum - datum.gstep + datum.gw / 2 : (datum.tier === 0 ? C0 + 7.0 + (datum.rn - 1) * 29 : datum.tier === 1 ? cEnd0 + 8 + 3.0 + (datum.rn - 1) * 9 : cEnd1 + 8 + 2.0 + (datum.rn - 1) * 6)"
    },
    {
     "type": "formula",
     "as": "hw",
     "expr": "datum.c >= 3 ? 28 : 10"
    },
    {
     "type": "formula",
     "as": "hfull",
     "expr": "22 + datum.c * 13"
    },
    {
     "type": "formula",
     "as": "cw",
     "expr": "datum.a >= 6 ? 14 : datum.a >= 3 ? 6 : 4"
    },
    {
     "type": "formula",
     "as": "cfull",
     "expr": "12 + datum.a * 13"
    },
    {
     "type": "formula",
     "as": "fr",
     "expr": "datum.k > 0 ? min(3.5 + 1.8 * datum.k, datum.a >= 6 ? 12 : datum.a >= 3 ? 5 : 2.5) : 0"
    },
    {
     "type": "formula",
     "as": "gh",
     "expr": "20 + datum.a * 8.5"
    },
    {
     "type": "formula",
     "as": "top",
     "expr": "datum.kind === ''dead'' ? datum.hfull + (datum.hal && datum.c >= 3 ? 22 : 0) : datum.kind === ''born'' ? datum.gh + 46 : datum.cfull + 7 + 2 * datum.fr + (datum.a >= 6 ? 26 : 0) + (datum.k === 0 ? 34 : 0)"
    }
   ]
  },
